"""Validate closed-form worst-case multiproof metrics by brute force."""
from itertools import combinations, product

from pqattest.merkle import _canonical_multiproof_nodes


def brute(L, H, k):
    worst_nodes = 0
    worst_internal = 0
    worst_wire_m = 0
    triple_worst = None
    for indices in combinations(range(L), k):
        m = len(_canonical_multiproof_nodes(indices, H))
        internal = sum(len({i >> l for i in indices}) for l in range(1, H + 1))
        worst_nodes = max(worst_nodes, m)
        worst_internal = max(worst_internal, internal)
        worst_wire_m = max(worst_wire_m, m)
        # subset maximising each of (wire proxy m, nodes m, internal) jointly:
        # check whether the triple maximiser exists
        if triple_worst is None or (m, m, internal) > triple_worst[:3]:
            triple_worst = (m, m, internal, indices)
    return worst_nodes, worst_internal, worst_wire_m


def formula_nodes(H, k):
    if k == 1 << H:
        return 0
    out = min(2, k)
    for l in range(1, H):
        two_l = 1 << l
        two_lp = two_l << 1
        q, r = divmod(k, two_lp)
        val = 2 * q + min(2, r) - (1 if r > two_l else 0)
        val = min(val, two_l)
        out += val
    return out


def formula_internal(H, k):
    out = 0
    for l in range(1, H + 1):
        out += min((1 << (H - l)), (k >> l) + min(1, k & ((1 << l) - 1)))
    return out


def max_triple(L, H, k):
    best = (-1, -1, -1)
    best_set = None
    for indices in combinations(range(L), k):
        m = len(_canonical_multiproof_nodes(indices, H))
        internal = sum(len({i >> l for i in indices}) for l in range(1, H + 1))
        # Pareto-maximal triple check: does one subset attain all three maxima?
        if (m, internal) > (best[0], best[2]):
            best = (m, best[1], internal)
    return best


def main():
    ok = True
    for H in range(1, 9):
        L = 1 << H
        for k in range(1, L + 1):
            wn, wi, ww = brute(L, H, k)
            fn = formula_nodes(H, k)
            fi = formula_internal(H, k)
            if fn != wn:
                print(f"NODES MISMATCH H={H} k={k}: formula {fn} brute {wn}")
                ok = False
            if fi != wi:
                print(f"INTERNAL MISMATCH H={H} k={k}: formula {fi} brute {wi}")
                ok = False
    # identity checks: m_max + internal_max == k*H
    for H in range(1, 9):
        for k in range(1, (1 << H) + 1):
            if formula_nodes(H, k) + formula_internal(H, k) != k * H:
                print(f"IDENTITY FAIL H={H} k={k}")
                ok = False

    # Check a single subset simultaneously achieves all three maxima
    # (wire bytes proxy = node count, node count, internal hashes).
    for H in range(1, 9):
        L = 1 << H
        for k in range(1, L + 1):
            wn, wi, _ = brute(L, H, k)
            joint = any(
                len(_canonical_multiproof_nodes(idx, H)) == wn
                and sum(len({i >> l for i in idx}) for l in range(1, H + 1)) == wi
                for idx in combinations(range(L), k)
            )
            if not joint:
                print(f"NO JOINT EXTREMAL H={H} k={k} m={wn} internal={wi}")
                ok = False

    # full-tree sanity: H small compare with real encode sizes
    print("ALL OK" if ok else "FAILURES")


if __name__ == "__main__":
    main()

