"""Validate closed-form worst-case multiproof metrics by brute force."""
import random

from pqattest.merkle import _canonical_multiproof_nodes


def metrics(indices, H):
    m = len(_canonical_multiproof_nodes(indices, H))
    internal = sum(len({i >> l for i in indices}) for l in range(1, H + 1))
    return m, internal


def formula_nodes(H, k):
    if k == 1 << H:
        return 0
    out = min(2, k)
    for l in range(1, H):
        two_l = 1 << l
        two_lp = two_l << 1
        q, r = divmod(k, two_lp)
        val = 2 * q + min(2, r) - (1 if r > two_l else 0)
        val = min(val, two_l)
        out += val
    return out


def formula_internal(H, k):
    out = 0
    for l in range(1, H + 1):
        out += min((1 << (H - l)), (k >> l) + min(1, k & ((1 << l) - 1)))
    return out


def check_range(H, ks, exhaustive, samples=200_000, seed=0):
    rng = random.Random(seed)
    L = 1 << H
    ok = True
    for k in ks:
        fn = formula_nodes(H, k)
        fi = formula_internal(H, k)
        wn = wi = -1
        joint = False
        if exhaustive:
            from itertools import combinations

            for indices in combinations(range(L), k):
                m, internal = metrics(indices, H)
                wn = max(wn, m)
                wi = max(wi, internal)
                if m == fn and internal == fi:
                    joint = True
        else:
            # random sampling must never exceed the formula
            seen = set()
            for _ in range(samples):
                while True:
                    picks = tuple(sorted(rng.sample(range(L), k)))
                    if picks not in seen:
                        seen.add(picks)
                        break
                m, internal = metrics(picks, H)
                if m > fn:
                    print(f"NODES EXCEEDED H={H} k={k}: {m} > {fn}")
                    ok = False
                if internal > fi:
                    print(f"INTERNAL EXCEEDED H={H} k={k}: {internal} > {fi}")
                    ok = False
            wn, wi = fn, fi  # sampling cannot confirm attainment
            # constructively: worst for internal = packed block (0..k-1)
            m, internal = metrics(tuple(range(k)), H)
            if internal != fi:
                print(f"PACKED FAIL INTERNAL H={H} k={k}: {internal} != {fi}")
                ok = False
            # worst for nodes: strided every-other... use explicit construction:
            # pick indices so pairs are avoided as much as possible:
            # greedy: choose residues with distinct (i>>1) parents first.
            constructed = _node_maximising_set(L, H, k)
            m, internal = metrics(constructed, H)
            if m != fn:
                print(f"CONSTRUCTED FAIL NODES H={H} k={k}: {m} != {fn}")
                ok = False
            joint = True  # constructive checks separately
        if exhaustive:
            if fn != wn:
                print(f"NODES MISMATCH H={H} k={k}: formula {fn} brute {wn}")
                ok = False
            if fi != wi:
                print(f"INTERNAL MISMATCH H={H} k={k}: formula {fi} brute {wi}")
                ok = False
            if not joint:
                print(f"NO JOINT EXTREMAL H={H} k={k}")
                ok = False
    return ok


def _node_maximising_set(L, H, k):
    """Greedy subset expected to attain the max carried-node count."""""
    chosen = []
    # at level 0, avoid pairing: pick indices whose index^1 not already picked
    for i in range(L):
        if len(chosen) >= k:
            break
        if (i ^ 1) not in chosen:
            chosen.append(i)
    # if still short, append rest
    for i in range(L):
        if len(chosen) >= k:
            break
        if i not in chosen:
            chosen.append(i)
    return tuple(sorted(chosen))


def main():
    ok = True
    # fully exhaustive for H <= 4
    for H in range(1, 5):
        L = 1 << H
        ok &= check_range(H, range(1, L + 1), True)
    # edge ks for larger H
    edge = {
        5: list(range(1, 7)) + list(range(26, 33)),
        6: list(range(1, 5)) + list(range(60, 65)),
        7: list(range(1, 4)) + list(range(125, 129)),
        8: list(range(1, 3)) + list(range(254, 257)),
    }
    for H, ks in edge.items():
        ok &= check_range(H, ks, True)
    # random sampling interior for H 5..8
    rng = random.Random(42)
    for H in range(5, 9):
        L = 1 << H
        inner = [k for k in range(1, L + 1) if k not in set(edge[H])]
        chosen_ks = [inner[0], L // 4, L // 2, (3 * L) // 4, inner[-1]]
        ok &= check_range(H, chosen_ks, False, samples=50_000)

    # identity: m_max + internal_max == k*H for all H,k
    for H in range(1, 9):
        for k in range(1, (1 << H) + 1):
            if formula_nodes(H, k) + formula_internal(H, k) != k * H:
                print(f"IDENTITY FAIL H={H} k={k}")
                ok = False

    print("ALL OK" if ok else "FAILURES")


if __name__ == "__main__":
    main()

