from pqattest.merkle import _canonical_multiproof_nodes


def metrics(indices, H):
    m = len(_canonical_multiproof_nodes(indices, H))
    internal = sum(len({i >> l for i in indices}) for l in range(1, H + 1))
    return m, internal


@lru_cache(maxsize=None)
def worst_nodes(H, k):
    if H == 1:
        return 1 if k == 1 else 0
    best = -1
    for j in range((k + 1) // 2, min(k, 1 << (H - 1)) + 1):
        best = max(best, 2 * j - k + worst_nodes(H - 1, j))
    return best


def worst_internal(H, k):
    return k + worst_nodes(H, k) - 1


@lru_cache(maxsize=None)
def worst_set(H, k):
    """Constructively realize an extremal k-subset of a height-H tree."""
    if H == 1:
        return (0,) if k == 1 else (0, 1)
    best_j, best_v = None, -1
    for j in range((k + 1) // 2, min(k, 1 << (H - 1)) + 1):
        v = 2 * j - k + worst_nodes(H - 1, j)
        if v > best_v:
            best_v, best_j = v, j
    parents = worst_set(H - 1, best_j)
    pairs = 2 * best_j - k  # number of parents expanded to both children
    indices = []
    for rank, parent in enumerate(parents):
        if rank < pairs:
            indices.extend((2 * parent, 2 * parent + 1))
        else:
            indices.append(2 * parent)
    return tuple(sorted(indices))


def main():
    ok = True
    # 1) exhaustive brute for H <= 4, every k
    for H in range(1, 5):
        L = 1 << H
        for k in range(1, L + 1):
            mn = mi = -1
            for indices in combinations(range(L), k):
                m, internal = metrics(indices, H)
                if internal != k + m - 1:
                    print(f"IDENTITY FAIL H={H} k={k} I={indices}")
                    ok = False
