            constructed = worst_set(H, k)
            if len(constructed) != k or len(set(constructed)) != k:
                print(f"BAD CONSTRUCTION SHAPE H={H} k={k}")
                ok = False
            if metrics(constructed, H) != (wn, wi):
                print(f"CONSTRUCTION FAIL H={H} k={k}")
                ok = False
            if not (0 <= wn <= k * H and wi == k + wn - 1):
                print(f"RANGE FAIL H={H} k={k}")
                ok = False

