                if picks in seen:
                    continue
                seen.add(picks)
                m, internal = metrics(picks, H)
                if m > wn or internal > wi or internal != k + m - 1:
                    print(f"SAMPLE FAIL H={H} k={k}")
                    ok = False

    print("ALL OK" if ok else "FAILURES")


if __name__ == "__main__":
    main()

